import numpy as np

class landscape:

    def __init__(self, dim=5):
        self.dim = dim
        self.alpha = 0.1  # Controls the balance between quadratic and harmonic terms

    def f(self, x):
        quadratic_term = np.sum(x**2)
        harmonic_term = self.alpha * np.sum(1 / (np.abs(x) + 1e-6))  # Avoid division by zero
        return quadratic_term + harmonic_term

import numpy as np

class HarmonicBasin:
    def __init__(self, dim=5):
        self.dim = dim
        self.centers = np.random.uniform(-4, 4, size=(10, dim))  # 10 random centers within bounds
        self.weights = np.random.uniform(0.1, 1.0, size=10)     # Random weights for each center

    def f(self, x):
        # Global minimum at origin
        global_term = np.sum(x**2)

        # Harmonic terms centered at random points
        harmonic_terms = np.zeros(10)
        for i in range(10):
            diff = x - self.centers[i]
            harmonic_terms[i] = self.weights[i] * np.sum(np.sin(diff) / (1 + np.abs(diff)))

        # Combine terms to create homogeneous basins
        return global_term + 0.5 * np.sum(harmonic_terms)
